test('partner chat reminder uses LinkedIn-style unread-count email',()=>{const worker=read('supabase/functions/partner-chat-reminders/index.ts');assert.match(worker,/subject='Vorlen has messaged you'/);assert.match(worker,/new \$\{unreadCount\===1\?'message':'messages'\} from Vorlen management/);assert.match(worker,/View messages/);assert.match(worker,/https:\/\/www\.vorlen\.co\.uk\/dashboard\/partner\/chat/);assert.match(worker,/managementUsers/);assert.match(worker,/managementMessages/);assert.match(worker,/partner_message_receipts/);assert.match(worker,/unreadCount<1/);assert.match(worker,/from:'Vorlen <contact@vorlen\.co\.uk>'/);});

test('system email footers do not expose the registered office address',()=>{const shared=read('supabase/functions/_shared/vorlen-email.ts'),automation=read('supabase/functions/process-automation-queue/index.ts'),chat=read('supabase/functions/partner-chat-reminders/index.ts'),invite=read('supabase/functions/partner-client-portal-invite/index.ts'),terms=read('supabase/functions/client-terms/index.ts');const termsEmail=terms.slice(0,terms.indexOf('const terms='));for(const emailTemplate of [shared,automation,chat,invite,termsEmail]){assert.doesNotMatch(emailTemplate,/Registered office:|10 South Street|OL16 2EP/);}assert.match(terms.slice(terms.indexOf('const terms=')),/Registered office:/);});

test('partner chat contexts resolve to partner-safe deep links',()=>{const chat=read('src/pages/PartnerChat.tsx');assert.match(chat,/function contextHref\(m:Message\)/);assert.match(chat,/client:'\/dashboard\/partner\/clients\?client='/);assert.match(chat,/job:'\/dashboard\/partner\/vacancies\?job='/);assert.match(chat,/candidate:access\.partnerCanSourceCandidates\?'\/dashboard\/partner\/candidates\/'\+id:'\/dashboard\/partner\/applications\?candidate='\+id/);assert.match(chat,/application:'\/dashboard\/partner\/applications\?application='/);assert.match(chat,/handoff:'\/dashboard\/partner\/handoffs\?handoff='/);assert.match(chat,/placement:'\/dashboard\/partner\/earnings\?placement='/);assert.match(chat,/commission:'\/dashboard\/partner\/earnings\?commission='/);assert.match(chat,/to=\{contextHref\(m\)\}/);});
test('partner chat deep links open or focus intended records',()=>{const clients=read('src/pages/PartnerClients.tsx'),ops=read('src/pages/PartnerOperations.tsx'),apps=read('src/pages/PartnerApplications.tsx');assert.match(clients,/params\.get\('client'\)/);assert.match(clients,/openClient\(c\)/);assert.match(ops,/section!=='vacancies'/);assert.match(ops,/params\.get\('job'\)/);assert.match(ops,/setSelectedJob\(job\)/);assert.match(ops,/params\.get\('handoff'\)/);assert.match(ops,/params\.get\('placement'\)/);assert.match(ops,/params\.get\('commission'\)/);assert.match(apps,/useSearchParams/);assert.match(apps,/params\.get\('application'\)/);assert.match(apps,/a\.id===linkedApplication/);});

