test('manager chat context picker is scoped to recipient partner access',()=>{const chat=read('src/pages/PartnerChat.tsx');assert.match(chat,/availableContextTypes=contextTypes\.filter/);assert.match(chat,/recipientCanClient/);assert.match(chat,/recipientCanClose/);assert.match(chat,/recipientCanSource/);assert.match(chat,/partner_assignments/);assert.match(chat,/partner_candidate_pipeline/);assert.match(chat,/partner_attributions/);assert.match(chat,/rows=rows\.filter\(x=>x\.partner_id===partnerUserId\)/);assert.match(chat,/rows=rows\.filter\(x=>x\.partner_user_id===partnerUserId\)/);assert.match(chat,/Partner-scoped context could not be verified\. No record was linked\./);assert.match(chat,/availableContextTypes\.map/);});

test('manager jobs support full vacancy detail and chat deep links',()=>{const jobs=read('src/pages/Jobs.tsx'),chat=read('src/pages/PartnerChat.tsx');assert.match(jobs,/useSearchParams/);assert.match(jobs,/params\.get\('job'\)/);assert.match(jobs,/setSelected\(found\)/);assert.match(jobs,/function openDetails/);assert.match(jobs,/View details/);for(const x of ['Vacancy brief','Compliance & worker particulars','Client instruction reference','Health & safety risks','Required experience, training, qualifications & authorisations','Minimum remuneration & benefits'])assert.ok(jobs.includes(x),x);assert.match(chat,/job:'\/dashboard\/jobs\?job='\+id/);});

test('partner chat preserves pasted rich formatting safely',()=>{const chat=read('src/pages/PartnerChat.tsx'),css=read('src/styles.css');assert.match(chat,/htmlToMessageMarkup/);assert.match(chat,/DOMParser/);assert.match(chat,/tag==='strong'\|\|tag==='b'/);assert.match(chat,/tag==='u'/);assert.match(chat,/tag==='ul'/);assert.match(chat,/tag==='ol'/);assert.match(chat,/onPaste=\{handleComposerPaste\}/);assert.match(chat,/function renderInline/);assert.match(chat,/chat-rich-body/);assert.match(chat,/<strong key=/);assert.match(chat,/<u key=/);assert.match(chat,/<em key=/);assert.match(chat,/<ul key=/);assert.match(chat,/<ol key=/);assert.doesNotMatch(chat,/dangerouslySetInnerHTML/);assert.match(css,/\.chat-rich-body ul/);});

test('partner chat rich paste handles styled spans and nested formatting',()=>{const chat=read('src/pages/PartnerChat.tsx');assert.match(chat,/function applyInlineMarkup/);assert.match(chat,/style\.fontWeight/);assert.match(chat,/numericWeight>=600/);assert.match(chat,/style\.fontStyle/);assert.match(chat,/textDecoration/);assert.match(chat,/decoration\.includes\('underline'\)/);assert.match(chat,/const inner=renderInline/);assert.match(chat,/<strong key=\{key\}>\{inner\}<\/strong>/);assert.match(chat,/<u key=\{key\}>\{inner\}<\/u>/);assert.match(chat,/<em key=\{key\}>\{inner\}<\/em>/);assert.doesNotMatch(chat,/dangerouslySetInnerHTML/);});

