test('partner chat reactions are secure realtime and mobile-ready',()=>{const chat=read('src/pages/PartnerChat.tsx'),css=read('src/styles.css'),migration=read('supabase/migrations/20261001013113_partner_chat_message_reactions.sql');for(const x of ['👍','❤️','😂','😮','😢','🙏'])assert.ok(chat.includes(x),x);assert.match(chat,/partner_message_reactions/);assert.match(chat,/onConflict:'message_id,user_id'/);assert.match(chat,/function reactionGroups/);assert.match(chat,/function startReactionPress/);assert.match(chat,/window\.setTimeout\(\(\)=>\{openReactionPicker\(m\.id\)/);assert.match(chat,/onPointerDown=\{e=>startReactionPress\(e,m\)\}/);assert.match(chat,/onPointerMove=\{moveReactionPress\}/);assert.match(chat,/SmilePlus/);assert.match(chat,/chat-reaction-picker/);assert.match(chat,/chat-reactions/);assert.match(chat,/table:'partner_message_reactions'/);assert.match(css,/\.chat-reaction-picker/);assert.match(css,/touch-action:pan-y/);assert.match(migration,/create table if not exists public\.partner_message_reactions/);assert.match(migration,/unique\(message_id,user_id\)/);assert.match(migration,/enable row level security/);assert.match(migration,/grant select,insert,update,delete on public\.partner_message_reactions to authenticated/);assert.match(migration,/private\.partner_chat_can_access/);assert.match(migration,/user_id=\(select auth\.uid\(\)\)/);assert.match(migration,/m\.deleted_at is null/);assert.match(migration,/alter publication supabase_realtime add table public\.partner_message_reactions/);assert.doesNotMatch(migration,/alter .*realtime\./i);});
test('partner chat reactions support one reaction per user with change and removal',()=>{const chat=read('src/pages/PartnerChat.tsx'),migration=read('supabase/migrations/20261001013113_partner_chat_message_reactions.sql');assert.match(chat,/existing\?\.emoji===emoji/);assert.match(chat,/\.delete\(\)\.eq\('id',existing\.id\)/);assert.match(chat,/\.upsert\(payload,\{onConflict:'message_id,user_id'\}\)/);assert.match(chat,/setReactions\(rows=>rows\.filter/);assert.match(chat,/optimistic:Reaction/);assert.match(migration,/partner_message_reactions_one_per_user unique\(message_id,user_id\)/);assert.match(migration,/Reaction identity fields are immutable/);});

test('reaction RLS binds message to the same conversation and company',()=>{const base=read('supabase/migrations/20261001013113_partner_chat_message_reactions.sql'),hardening=read('supabase/migrations/20261001013559_harden_partner_chat_reaction_scope.sql');for(const s of [base,hardening]){assert.match(s,/m\.id=partner_message_reactions\.message_id/);assert.match(s,/m\.conversation_id=partner_message_reactions\.conversation_id/);assert.match(s,/m\.company_id=partner_message_reactions\.company_id/);assert.doesNotMatch(s,/m\.conversation_id=m\.conversation_id/);assert.doesNotMatch(s,/m\.company_id=m\.company_id/);}});

