test('reaction tray is anchored to the selected message stack',()=>{const chat=read('src/pages/PartnerChat.tsx'),css=read('src/styles.css');assert.match(chat,/chat-message-stack/);assert.match(css,/\.chat-message-stack\{position:relative/);assert.match(css,/\.chat-reaction-picker\{position:absolute/);assert.match(css,/top:calc\(100% \+ 7px\)/);assert.match(css,/\.chat-message\.in \.chat-reaction-picker\{left:0\}/);assert.match(css,/\.chat-message\.out \.chat-reaction-picker\{right:0\}/);assert.match(css,/\.chat-reactions\{display:flex/);assert.match(css,/\.chat-scroll-end\{height:58px/);assert.match(css,/border-radius:999px/);assert.doesNotMatch(css,/\.chat-reaction-picker\{position:fixed/);});


test('partner typing uses a shared acknowledged realtime broadcast channel',()=>{const chat=read('src/pages/PartnerChat.tsx'),css=read('src/styles.css');assert.match(chat,/supabase\.channel\(`partner-chat-db-\$\{conversationId\}`,\{config:\{broadcast:\{ack:true\}\}\}\)/);assert.doesNotMatch(chat,/partner-chat-db-\$\{conversationId\}-\$\{me\}/);assert.match(chat,/\.on\('broadcast',\{event:'typing'\}/);assert.match(chat,/event:'typing',payload:\{user_id:me,active\}/);assert.match(chat,/chatChannelRef\.current=ch/);assert.doesNotMatch(chat,/payload\.user_id===me/);assert.match(chat,/setTypingSignalUntil\(active\?Date\.now\(\)\+5000:0\)/);assert.match(chat,/className=\{`chat-message \$\{typingSide\} chat-typing-message`\}/);assert.match(css,/\.chat-typing-bubble/);assert.match(css,/@media\(prefers-reduced-motion:reduce\)/);});


